const sampleQuestionIds = new Set(['APT-143','GS-284','RSN-091','GS-307','APT-162','RSN-114','GS-331','APT-180','RSN-137']);
const storedQuestions = JSON.parse(localStorage.getItem('exam-prep-questions') || localStorage.getItem('prepledger-questions') || '[]');
let questions = storedQuestions.filter(question => !sampleQuestionIds.has(question.id));
const nowTs = Date.now();
let needsDateInit = false;
questions.forEach((q, idx) => {
  if (!q.createdAt) {
    const dayOffset = idx % 6;
    q.createdAt = new Date(nowTs - (dayOffset * 86400000)).toISOString();
    needsDateInit = true;
  }
});
if (needsDateInit) localStorage.setItem('exam-prep-questions', JSON.stringify(questions));

function isSameDate(isoStr, targetDate = new Date()) {
  if (!isoStr) return false;
  const d = new Date(isoStr), t = new Date(targetDate);
  if (isNaN(d.getTime())) return false;
  return d.getFullYear() === t.getFullYear() && d.getMonth() === t.getMonth() && d.getDate() === t.getDate();
}

function isWithinPastDays(isoStr, numDays = 6) {
  if (!isoStr) return false;
  const d = new Date(isoStr).getTime();
  if (isNaN(d)) return false;
  const cutoff = Date.now() - (numDays * 24 * 60 * 60 * 1000);
  return d >= cutoff;
}

