function prepareRoughPages(testQuestions=[]){const saved=new Map(getWeeklyNotes().map(page=>[page.questionId,page]));const pages=testQuestions.map((question,index)=>saved.get(question.id)||({questionId:question.id,questionNumber:index+1,questionText:question.text,imageData:''}));saveWeeklyNotes(pages);return pages}
function blankCanvas(context,canvas){context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.strokeStyle='#d9e5e0';context.lineWidth=2;for(let y=110;y<canvas.height;y+=72){context.beginPath();context.moveTo(50,y);context.lineTo(canvas.width-50,y);context.stroke()}context.strokeStyle='#e9b4b4';context.beginPath();context.moveTo(140,40);context.lineTo(140,canvas.height-40);context.stroke()}
function mountRoughCanvas(canvas,page,onSave){const context=canvas.getContext('2d');blankCanvas(context,canvas);if(page.imageData){const image=new Image();image.onload=()=>context.drawImage(image,0,0,canvas.width,canvas.height);image.src=page.imageData}let drawing=false,last=null;const position=event=>{const bounds=canvas.getBoundingClientRect();return {x:(event.clientX-bounds.left)*canvas.width/bounds.width,y:(event.clientY-bounds.top)*canvas.height/bounds.height}};const save=()=>{page.imageData=canvas.toDataURL('image/jpeg',.72);onSave()};canvas.onpointerdown=event=>{drawing=true;last=position(event);canvas.setPointerCapture(event.pointerId)};canvas.onpointermove=event=>{if(!drawing)return;const next=position(event);context.strokeStyle='#163230';context.lineWidth=7;context.lineCap='round';context.beginPath();context.moveTo(last.x,last.y);context.lineTo(next.x,next.y);context.stroke();last=next};canvas.onpointerup=()=>{if(drawing){drawing=false;save()}};canvas.onpointercancel=()=>{if(drawing){drawing=false;save()}}}
function roughPdfBlob(pages){if(!window.jspdf?.jsPDF)throw new Error('PDF tools are still loading. Please try again.');const document=new window.jspdf.jsPDF({unit:'pt',format:'a4',compress:true});pages.forEach((page,index)=>{if(index)document.addPage();document.setFont('helvetica','bold');document.setFontSize(15);document.text('Exam Prep - Weekly Rough Work',40,45);document.setFont('helvetica','normal');document.setFontSize(10);document.text(`Question ${page.questionNumber}`,40,67);const questionLines=document.splitTextToSize(page.questionText||'Blank rough-work page',515);document.text(questionLines,40,84);const top=Math.min(160,100+questionLines.length*14);if(page.imageData){document.addImage(page.imageData,'JPEG',40,top,515,644)}else{document.setDrawColor(225,225,225);for(let y=top+24;y<790;y+=24)document.line(40,y,555,y)}});return document.output('blob')}
