async function uploadRoughWorkPdf(){const pages=getWeeklyNotes();if(!pages.length){toast('Open a weekly mock to create rough-work pages.');return}try{const blob=roughPdfBlob(pages);const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)});const response=await fetch('/api/upload-rough-work',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileName:`weekly-rough-work-${Date.now()}.pdf`,pdfBase64:base64})});const body=await response.json();if(!response.ok)throw new Error(body.error||'Unable to save the PDF to S3.');toast('Rough-work PDF saved to S3.');return body}catch(error){toast(error.message||'Unable to save the PDF to S3.')}}
function pdfSafe(value=''){return String(value).replace(/[^\x20-\x7E]/g,' ').replace(/[\\()]/g,'\\$&')}
function wrapPdfText(value,max=88){const words=pdfSafe(value).split(/\s+/),lines=[];let line='';words.forEach(word=>{if((line+' '+word).trim().length>max&&line){lines.push(line);line=word}else line=(line+' '+word).trim()});if(line)lines.push(line);return lines}
function makePdf(title,lines){const pageLines=lines.reduce((pages,line)=>{let current=pages[pages.length-1];if(current.length>=44){current=[];pages.push(current)}current.push(line);return pages},[[]]);const pageIds=pageLines.map((_,index)=>5+index*2);const objects=['<< /Type /Catalog /Pages 2 0 R >>',`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];pageLines.forEach((page,index)=>{const content=`BT /F1 10 Tf 45 800 Td (${pdfSafe(title)}) Tj 0 -22 Td /F1 8 Tf ${page.map((line,i)=>`${i?'0 -15 Td ':''}(${pdfSafe(line)}) Tj`).join(' ')} ET`;const contentId=4+index*2;objects.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${contentId} 0 R >>`)});let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((object,index)=>{offsets.push(pdf.length);pdf+=`${index+1} 0 obj\n${object}\nendobj\n`});const xref=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(offset=>String(offset).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'})}
function getTimestampedFilename(prefix='exam-paper'){const d=new Date(),pad=n=>String(n).padStart(2,'0'),yyyy=d.getFullYear(),mm=pad(d.getMonth()+1),dd=pad(d.getDate()),hh=pad(d.getHours()),min=pad(d.getMinutes());return `${prefix}_${yyyy}-${mm}-${dd}_${hh}-${min}.pdf`}
